 \draw[gray!60,densely dotted] ($(X.west)+(0,0.35)$) -- ($(X.east)+(0,0.35)$);
 \node[draw,densely dotted,rounded corners=5pt,inner sep=4pt,fit=(z)(u2),label={[slbl]left:$S$}] {};

 \draw[complete] (NX.east) -- (X.west);
 \draw[complete] (V.east) -- (NY.west);
