 \node[slbl,align=center] at (-1.95,-0.55) {$F_X=f(N_X)$\\$|F_X|\le s$};
 \node[slbl,align=center] at (5.35,-0.45) {$F_Y=f(N_Y)$\\$|F_Y|\le r$};
 \node[slbl,align=right,anchor=east] at (-0.75,1.35) {$X_0$: lists $L(z)$,\\ $f$-colours in $R(z)$};
